/** Source-reviewed local access routes for six further Scottish localities. */
import { pathway } from "./internationalSupportDirectoryPathway.js";

const UK = "United Kingdom";
const reviewedAt = "2026-11-20";
const records = [];

function add(city, category, slug, name, type, description, phone, url, source, extra = {}) {
  const localitySlug = city.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  records.push(pathway(UK, "GB", category, `scotland-${localitySlug}-${slug}`, name, type, description, phone, url, source, {
    city,
    state: "Scotland",
    region: `${city}, Scotland`,
    checkedAt: reviewedAt,
    ...extra,
  }));
}

// Paisley — council, NHS and community-provider access; referral, safety and food rules are explicit.
add("Paisley", "programs", "adult-cmht", "Paisley Community Mental Health Team", "Adult community mental-health assessment and continuing care", "NHSGGC lists the Renfrewshire CMHT at the Charleston Centre. Access is normally by GP or Social Services referral; contact the team or referrer to confirm catchment and next steps. This is not an emergency or walk-in clinic.", "0141 618 5600", "https://www.nhsggc.scot/your-health/heads-up-mental-health-support/services-and-support/mental-health-services/", "NHS Greater Glasgow and Clyde", { address: "Charleston Centre, 49 Neilston Road, Paisley PA2 6LY", locationLine: "Renfrewshire · GP/Social Services referral · confirm appointment" });
add("Paisley", "programs", "alcohol-drug-recovery", "Renfrewshire Alcohol and Drug Recovery Service", "Open-access alcohol and drug treatment, harm reduction and recovery support", "NHSGGC describes self-referral and partner referral access, with assessment, medication and psychological support, harm reduction, naloxone, family support and recovery pathways. Call to discuss the right local service and current access; treatment follows assessment.", "0300 300 1199", "https://www.nhsggc.scot/your-health/central-and-local-alcohol-and-drug-recovery-services/", "NHS Greater Glasgow and Clyde / Renfrewshire Alcohol and Drug Recovery Service", { alternatePhone: "Paisley service listed at Back Sneddon Centre: 0141 618 2585", address: "Back Sneddon Centre, 20 Back Sneddon Street, Paisley PA3 2DJ", locationLine: "Renfrewshire · self-referral welcome · ask for the local intake route" });
add("Paisley", "programs", "dykebar-alcohol-problems-clinic", "Dykebar Hospital Alcohol Problems Clinic", "Outpatient alcohol-problems assessment and care", "NHS Greater Glasgow and Clyde lists a day service for alcohol problems at Dykebar Hospital. Call the clinic to ask about referral, assessment and current appointments; this is a hospital clinic, not a walk-in detox or emergency service.", "0141 314 4106", "https://www.nhsggc.scot/hospitals-services/mental-health-hospitals-centres-teams/dykebar-hospital/", "NHS Greater Glasgow and Clyde", { address: "Dykebar Hospital, Grahamston Road, Paisley PA2 7DE", locationLine: "Outpatient clinic · phone to confirm referral and appointment" });
add("Paisley", "peer", "preshal-community-dropin", "The Preshal Trust — Paisley drop-in and community support", "Community meals, social connection and practical wellbeing support", "The Preshal Trust describes a Paisley drop-in with breakfast and lunch clubs, activities, cooking sessions and one-to-one practical and emotional support. Contact the provider to confirm current sessions, suitability and accessibility before travelling.", null, "https://www.preshaltrust.org.uk/paisley", "The Preshal Trust", { address: "20 Neilston Road, Paisley PA2 6LN", locationLine: "Community drop-in · check current timetable with provider" });
add("Paisley", "peer", "ramh-community-support", "RAMH — community mental-health support", "Community connection, recovery and wellbeing support", "Recovery Across Mental Health provides local community support alongside its crisis team. Use its service pages or contact the organisation to ask which group or one-to-one option fits your needs and whether a referral is required; availability varies by service.", "0141 847 8900", "https://ramh.org/", "Recovery Across Mental Health (RAMH)", { address: "41 Blackstoun Road, Paisley PA3 1LU", locationLine: "Renfrewshire services · contact to check eligibility and current sessions" });
add("Paisley", "housing", "housing-options-homelessness", "Renfrewshire Council — housing options and homelessness response", "Housing assessment and urgent temporary-accommodation contact", "Renfrewshire Council directs people who need temporary accommodation tonight to its emergency number and people seeking a permanent housing solution to Housing Options. Contact for an assessment; temporary accommodation and longer-term housing depend on the council's assessment and availability.", "0300 300 1203", "https://www.renfrewshire.gov.uk/housing/homelessness-help-and-advice/how-you-can-help-homeless-person", "Renfrewshire Council", { alternatePhone: "Need a temporary place tonight: 0800 121 4466", locationLine: "Renfrewshire residents · call to be assessed · no placement is guaranteed" });
add("Paisley", "housing", "vulnerable-housing-support", "Renfrewshire Council — housing support for vulnerable adults", "Tenancy sustainment and independent-living support", "The council offers free housing support to eligible people aged 16+ who are at risk of homelessness or struggle to maintain a home because of disability, illness, addiction or domestic abuse. Ask for a referral discussion; the council assesses eligibility and needs.", "0300 300 0344", "https://www.renfrewshire.gov.uk/housing/housing-support-vulnerable-people-0", "Renfrewshire Council", { email: "housingsupportreferral@renfrewshire.gov.uk", locationLine: "Renfrewshire · application/referral and assessment required" });
add("Paisley", "food.essentials", "foodbank-paisley-centre", "Renfrewshire Foodbank — Paisley distribution centre", "Emergency food parcels through local referral agencies", "The foodbank requires a valid voucher from a referral partner. Its Paisley distribution centre is at Paisley Baptist Church; call to ask a local agency about a voucher and confirm the current collection session before travelling. Parcels and stock are not guaranteed.", "0300 102 2500", "https://renfrewshire.foodbank.org.uk/locations/", "Renfrewshire Foodbank / Trussell", { address: "Paisley Baptist Church, 14 Lady Lane, Paisley PA1 2LJ", locationLine: "Voucher referral required · listed Monday, Wednesday and Friday sessions · confirm first" });
add("Paisley", "food.essentials", "star-project-pantry", "STAR Project — community pantry and essentials", "Food access and practical community support", "Renfrewshire Council lists STAR Project among local food-support options. Contact the project to ask about current pantry arrangements, any contribution or collection requirements, and other support; availability can change.", "0141 889 5850", "https://engagerenfrewshire.org/cost-of-living/", "Engage Renfrewshire cost-of-living directory", { address: "12–14 Wallace Street, Paisley PA3 2BU", locationLine: "Call to arrange/check a collection time and current pantry access" });
add("Paisley", "food.essentials", "saint-matthews-breakfast", "Saint Matthew’s Church — tea and toast", "Free community breakfast and connection", "Renfrewshire Council lists a Paisley tea-and-toast session on Monday mornings. Confirm that the session is still running and check accessibility before travelling; this is a community meal, not a food parcel or emergency accommodation service.", null, "https://www.renfrewshire.gov.uk/housing/homelessness-help-and-advice/how-you-can-help-homeless-person", "Renfrewshire Council", { address: "Gordon Street, Paisley", locationLine: "Monday 10am–12pm listed · reconfirm before travel" });
add("Paisley", "grants", "advice-works", "Advice Works — Renfrewshire money and benefits advice", "Free independent advice on benefits, debt, budgeting and housing costs", "The council's Advice Works team can check benefit entitlement, help with debt and budgeting, and advise on rent or mortgage arrears. Phone or use the council referral form; advice does not guarantee an award or grant.", "0300 300 1238", "https://www.renfrewshire.gov.uk/benefits-and-money/help-money-and-benefits", "Renfrewshire Council", { email: "adviceworks@renfrewshire.gov.uk", locationLine: "Renfrewshire residents · phone or online referral · weekday service" });
add("Paisley", "grants", "scottish-welfare-fund", "Renfrewshire Scottish Welfare Fund", "Assessed Crisis Grants and Community Care Grants", "Renfrewshire Council accepts Crisis Grant and Community Care Grant applications. Awards are discretionary, based on individual circumstances and limited resources; apply through the council and contact Advice Works if help with the application is needed.", "0300 300 0204", "https://www.renfrewshire.gov.uk/benefits-and-money/scottish-welfare-fund", "Renfrewshire Council", { locationLine: "Local authority application · eligibility and award are assessed; no payment is guaranteed" });
add("Paisley", "hotlines", "first-crisis", "RAMH FIRST Crisis — Renfrewshire mental-health crisis support", "Out-of-hours short-term mental-health crisis support", "RAMH's FIRST Crisis service supports people aged 16+ who live in Renfrewshire and are experiencing a mental-health crisis. Call for immediate conversation and support; it is not an emergency dispatch service. If there is immediate danger, call 999; NHS 24 is 111.", "0800 221 8929", "https://ramh.org/services-old/crisis-support/", "Recovery Across Mental Health (RAMH)", { alternatePhone: "0141 848 9090", locationLine: "Renfrewshire residents aged 16+ · hours vary by weekday/weekend · not emergency dispatch" });

// Falkirk — NHS/council pathways plus direct recovery, food and local advice contacts.
add("Falkirk", "programs", "community-mental-health-team", "Falkirk Integrated Community Mental Health Team", "Assessment and continuing community mental-health support", "Falkirk Council and NHS Forth Valley describe an integrated team for people with severe or continuing mental-health needs. Access is through a GP, Social Work or another health/social-care professional; the team assesses each referral and is not a walk-in crisis clinic.", "01324 506070", "https://www.falkirk.gov.uk/health-and-wellbeing/mental-health/integrated-community-mental-health-teams", "Falkirk Council / NHS Forth Valley", { locationLine: "Falkirk area · referral and clinical assessment required" });
add("Falkirk", "programs", "substance-use-service", "NHS Forth Valley Substance Use Service — Falkirk", "Community alcohol and drug treatment and harm-reduction care", "NHS Forth Valley lists outpatient appointments at Falkirk Community Hospital with a multidisciplinary team. Call to discuss referral and clinic access; opening hours and assessment apply, and the service is not emergency response.", "01324 673670", "https://nhsforthvalley.com/health-services/az-of-services/substance-misuse-service/", "NHS Forth Valley", { address: "Falkirk Community Hospital, Falkirk FK1 5SU", locationLine: "Outpatient appointments · listed weekdays 9:30am–5pm · call first" });
add("Falkirk", "programs", "cgl-recovery", "Change Grow Live — Forth Valley Recovery Service", "Free confidential substance-use support and recovery planning", "The provider lists its Falkirk recovery hub and direct access by phone. Services include recovery-focused support and harm-reduction pathways; contact to discuss eligibility, appointment or drop-in access and current hours.", "0808 196 2188", "https://www.changegrowlive.org/service/forth-valley-recovery/hubs", "Change Grow Live", { address: "27–29 Vicar Street, Falkirk FK1 1LL", locationLine: "Falkirk hub · phone for current access and referral details" });
add("Falkirk", "peer", "fdamh", "Falkirk & District Association for Mental Health (FDAMH)", "Free one-to-one and group wellbeing support", "FDAMH offers free one-to-one and group mental-health support for Falkirk and District residents, including adults, young people, families and carers. Use its referral form or call to arrange an appointment; this is not a 24-hour crisis service.", "01324 671600", "https://fdamh.org.uk/", "Falkirk & District Association for Mental Health", { email: "admin@fdamh.org.uk", locationLine: "Falkirk and District · referral form/appointment · weekday hours listed" });
add("Falkirk", "peer", "forth-valley-recovery-communities", "Forth Valley Recovery — community support and groups", "Recovery community and peer-support navigation", "The Forth Valley recovery directory links people to local peer and community services alongside treatment. Use the service finder or call Change Grow Live to ask about current Falkirk groups and meeting access; group schedules may change.", "0808 196 2188", "https://www.forthvalleyrecovers.com/find-support.html", "Forth Valley Recovery / Change Grow Live", { locationLine: "Falkirk/Forth Valley · confirm group schedule, access and eligibility" });
add("Falkirk", "housing", "housing-needs-homelessness", "Falkirk Council Housing Needs Team — homelessness assessment", "Prevention, housing options and emergency accommodation assessment", "The council can assess people who are homeless or at risk and may arrange temporary accommodation based on need and availability. Contact during office hours; for a safe place tonight use the separately listed out-of-hours number.", "01324 506070", "https://www.falkirk.gov.uk/homelessness/homelessness", "Falkirk Council", { email: "HousingNeeds@falkirk.gov.uk", locationLine: "Weekdays 9am–5pm listed · assessment required · accommodation not guaranteed" });
add("Falkirk", "housing", "tenancy-support", "Falkirk Council — Tenancy Sustainment Service", "Free housing support to prevent homelessness and sustain a tenancy", "Falkirk Council says its Tenancy Support Team helps eligible residents manage a tenancy, rent arrears, resettlement and referrals to other services. Residents or another service can contact the team; assessment and an agreed support plan follow.", "01324 503600", "https://www.falkirk.gov.uk/tenant-support/tenant-support", "Falkirk Council / Wheatley Care", { email: "tenancysupportteam@falkirk.gov.uk", locationLine: "Falkirk Council area · eligibility and assessment apply" });
add("Falkirk", "food.essentials", "falkirk-foodbank-delivery", "Falkirk Foodbank — emergency food parcel delivery", "Voucher-referred emergency food support delivered across Falkirk District", "Falkirk Foodbank provides parcel delivery across the district through an agency voucher system. Ask a local referral agency for help and contact the foodbank to confirm the process; the warehouse is not a parcel collection point and stock is not guaranteed.", "07809 340919", "https://falkirk.foodbank.org.uk/locations/", "Falkirk Foodbank / Trussell", { alternatePhone: "07809 340918", address: "Unit 1, Tamfourhill Industrial Estate, Tamfourhill Avenue, Falkirk FK1 4RT", locationLine: "Delivery only · voucher referral required · warehouse is not parcel collection" });
add("Falkirk", "food.essentials", "forth-valley-food-map", "Forth Valley Sustainable Food Directory and Map", "Local foodbank, community café and low-cost-food navigator", "NHS Forth Valley's food-access page links to its regional directory and map of emergency food providers, community cafés and related support. Use the map to locate a service, then contact the provider directly to confirm referral, cost, current hours and food availability.", null, "https://nhsforthvalley.com/health-services/health-promotion/nutrition/access-to-food-food-security/", "NHS Forth Valley / Forth Valley Food Futures", { locationLine: "Falkirk and Forth Valley · service locator, not a provider or stock guarantee" });
add("Falkirk", "grants", "advice-support-hubs", "Falkirk Council Advice and Support Hubs", "In-person help with council benefits, rent, money and cost-of-living needs", "The council lists three free Advice and Support Hubs, including the Falkirk Library central hub, with weekday sessions. Contact the hub about a suitable location, current hours and the documents needed; staff can help with applications but do not guarantee awards.", "01324 506070", "https://www.falkirk.gov.uk/benefits/cost-of-living-support/where-to-go-for-help", "Falkirk Council", { address: "Central Advice and Support Hub, Falkirk Library, Hope Street, Falkirk FK1 5AU", email: "centralhub@falkirk.gov.uk", locationLine: "Three hub locations · Monday–Friday 10am–4pm listed · check current access" });
add("Falkirk", "grants", "scottish-welfare-fund", "Falkirk Scottish Welfare Fund — Crisis Grant", "Assessed grant for urgent essential living costs", "The council directs residents facing an immediate crisis to its Scottish Welfare Fund team. Crisis Grants may help with essentials such as food, heating or electricity; eligibility, need and available funds are assessed, and an award is not guaranteed.", "0808 100 3161", "https://www.falkirk.gov.uk/benefits/cost-of-living-support/where-to-go-for-help", "Falkirk Council", { locationLine: "Falkirk residents · apply to the local council · assessed and budget-limited" });
add("Falkirk", "hotlines", "out-of-hours-homelessness", "Falkirk Council — 24-hour homeless emergency line", "Out-of-hours homelessness and temporary accommodation assessment", "If you are homeless and have nowhere safe to stay, the council publishes this freephone for weekdays overnight, weekends and public holidays. Staff assess circumstances and may arrange temporary accommodation; call 999 for immediate danger to life.", "0800 587 4440", "https://www.falkirk.gov.uk/homelessness/homelessness", "Falkirk Council", { alternatePhone: "Out of hours: 01324 506070", locationLine: "Weekdays 5pm–9am and all day weekends/public holidays · assessment and availability apply" });

// Kirkcaldy — locality-specific Fife food sites, recovery and advice access.
add("Kirkcaldy", "programs", "community-mental-health-team", "NHS Fife Kirkcaldy Community Mental Health Team", "Assessment and continuing adult community mental-health care", "NHS Fife lists Kirkcaldy as one of five CMHT localities. Referrals normally come from a GP or another health professional; the team assesses referrals and arranges an appointment if accepted. It is not open to self-referral or a crisis walk-in.", null, "https://www.nhsfife.org/services/all-services/mental-health/community-mental-health-team/", "NHS Fife", { locationLine: "Kirkcaldy and surrounding areas · GP/health-professional referral" });
add("Kirkcaldy", "programs", "addiction-services", "NHS Fife Addiction Services — Kirkcaldy clinic", "Alcohol and drug treatment, recovery planning and harm reduction", "NHS Fife lists Addiction Services at Whytemans Brae Hospital, including nursing assessment, community or inpatient alcohol detox assessment, psychosocial support, groups and harm reduction. Call to ask about referral and the appropriate clinic; treatment depends on assessment.", "01592 643355", "https://www.nhsfife.org/services/all-services/addiction-services/", "NHS Fife", { address: "Whytemans Brae Hospital, Whyteman’s Brae, Kirkcaldy KY1 2NA", locationLine: "Call NHS Fife to confirm referral and current clinic access" });
add("Kirkcaldy", "programs", "dapl-substance-support", "Drugs, Alcohol and Psychotherapies Limited (DAPL) — Fife", "Free counselling and support for people and families affected by substance use", "NHS Fife identifies DAPL as a local service offering one-to-one counselling, support and advice to young people, adults and families affected by substance use or emotional distress. Contact to discuss age/catchment, referral and appointment access.", "01333 422277", "https://www.nhsfife.org/pain-talking/useful-information-and-resources/", "NHS Fife", { alternatePhone: "Text: 07584 233877", locationLine: "Fife service with Kirkcaldy access · contact to confirm eligibility and appointment" });
add("Kirkcaldy", "peer", "fass-adapt-recovery", "Fife Alcohol Support Service — ADAPT and peer recovery", "Substance-use triage, recovery clinics and peer support", "FASS describes ADAPT as a Fife-wide triage and recovery service with drop-in clinics and referral to suitable providers; its peer groups support clients and people affected by substance use. Call to confirm the nearest Kirkcaldy session and whether it is suitable for self-referral.", "01592 321321", "https://www.firstforfife.co.uk/other-support-services", "FIRST / Fife Alcohol Support Service", { locationLine: "Fife-wide · check clinic timetable before travelling · not emergency response" });
add("Kirkcaldy", "peer", "nourish-family-support", "Nourish Support Centre — Kirkcaldy family community hub", "Peer connection and practical support for families with additional support needs", "Nourish offers a community hub and support groups for Fife families with additional support needs. Contact to discuss referral and which group is appropriate; some activities are family-specific and appointments may be needed.", "01592 653639", "https://nourishsupportcentre.com/", "Nourish Support Centre", { email: "info@nourishsupportcentre.com", address: "1C Barclay Court, Mitchelston Estate, Kirkcaldy KY1 3WE", locationLine: "Fife families with additional support needs · check group and appointment access" });
add("Kirkcaldy", "peer", "linton-lane-community-centre", "Linton Lane Community Centre — community connection", "Local community activities and supported social connection", "Fife Council lists Linton Lane as a community venue and food-support location. Contact the centre to ask about current groups and activities, accessibility and any booking requirements; the venue's programme can change.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/kirkcaldy-area", "Fife Council", { address: "Linton Lane, Kirkcaldy KY2 6LF", locationLine: "Check the centre's current programme and access before travelling" });
add("Kirkcaldy", "housing", "homelessness-prevention", "Fife Council — homelessness prevention and temporary accommodation", "Housing options assessment and emergency accommodation", "Fife Council asks people who are homeless or at risk to contact its housing team early. It can assess needs, offer temporary accommodation when needed and advise on longer-term options; placement area and availability depend on the case.", "03451 550033", "https://www.fife.gov.uk/housing/homelessness-and-prevention", "Fife Council", { alternatePhone: "24-hour homeless emergencies: 0800 028 6231", locationLine: "Fife-wide · daytime housing advice and separate 24/7 emergency number" });
add("Kirkcaldy", "housing", "housing-options-plan", "Fife Council Housing Options Plan", "Personalised assessment of social and private housing routes", "Fife Council's Housing Options Plan gives recommendations based on a person's circumstances and explains how to apply. It is not itself an application for social housing; contact the advice line or book in-person help if you need support completing it.", "03451 550033", "https://www.fife.gov.uk/housing/housing-options", "Fife Council", { locationLine: "Fife-wide service · housing advice and appointment support available" });
add("Kirkcaldy", "food.essentials", "foodbank-park-road", "Kirkcaldy Food Bank — Park Road Centre", "Free emergency food parcels", "Fife Council lists Park Road Centre as a Kirkcaldy foodbank location where self-referral is accepted. Confirm current session and what identification or information is needed before travelling; food parcels depend on current service arrangements.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/kirkcaldy-area", "Fife Council / Kirkcaldy Food Bank", { address: "Park Road Centre, 2 Park Road, Kirkcaldy KY1 3EL", locationLine: "Self-referral listed · weekday sessions vary · check current details" });
add("Kirkcaldy", "food.essentials", "foodbank-new-volunteer-house", "Kirkcaldy Food Bank — New Volunteer House", "Free emergency food parcels", "Fife Council lists New Volunteer House as a Kirkcaldy Food Bank distribution centre. Self-referral is listed at this site; check the provider's current session and collection arrangements before travelling.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/kirkcaldy-area", "Fife Council / Kirkcaldy Food Bank", { address: "16 East Fergus Place, Kirkcaldy KY1 1XT", locationLine: "Self-referral listed · Monday, Wednesday and Friday hours listed · confirm first" });
add("Kirkcaldy", "food.essentials", "foodbank-linton-lane", "Kirkcaldy Food Bank — Linton Lane Centre", "Free emergency food parcels", "Fife Council lists Linton Lane Centre as a Kirkcaldy Food Bank location where self-referral is accepted. Contact the provider to verify current opening time, referral and parcel availability before travelling.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/kirkcaldy-area", "Fife Council / Kirkcaldy Food Bank", { address: "Linton Lane Centre, Kirkcaldy KY2 6LF", locationLine: "Self-referral listed · check current session and availability" });
add("Kirkcaldy", "grants", "fife-benefits-money-advice", "Fife Council — benefits and money advice support", "Benefit checks, cost-of-living appointments and local advice sessions", "Fife Council provides a Community Support helpline and face-to-face sessions in the Kirkcaldy area to help with benefit checks, heating costs, food access and money advice. Call to arrange an appointment and confirm current venue and eligibility; this service does not guarantee a benefit award.", "0800 952 0330", "https://www.fife.gov.uk/benefits-money-advice/get-support", "Fife Council", { locationLine: "Kirkcaldy area sessions · helpline weekdays 9am–5pm listed" });
add("Kirkcaldy", "grants", "citizens-advice-rights-fife", "Citizens Advice and Rights Fife (CARF)", "Independent advice on benefits, debt, housing and money", "Fife Council lists CARF as a route for foodbank access and benefits/money advice. Contact the service to discuss the issue, appointment or referral route; advice can support applications but does not decide or guarantee awards.", "03451 400095", "https://www.fife.gov.uk/benefits-money-advice/get-support", "Fife Council / Citizens Advice and Rights Fife", { locationLine: "Fife-wide advice · call to confirm appropriate local appointment" });
add("Kirkcaldy", "hotlines", "fife-out-of-hours-homelessness", "Fife Council — 24-hour homeless emergency line", "Out-of-hours housing assessment if you have nowhere safe to stay", "The council publishes a free 24-hour number for homeless emergencies. Call if you have nowhere safe to stay; the council assesses the situation and may offer temporary accommodation. In immediate danger call 999.", "0800 0286231", "https://www.fife.gov.uk/contact-us/contact-us-3/phone-numbers", "Fife Council", { locationLine: "24 hours, every day · Fife-wide · assessment and availability apply" });

// Dunfermline — local NHS bases, housing access and a broad set of named community food/support venues.
add("Dunfermline", "programs", "community-mental-health-team", "NHS Fife Dunfermline Community Mental Health Team", "Assessment and ongoing adult community mental-health care", "NHS Fife lists Dunfermline as a CMHT locality covering its surrounding area. A GP or another health professional normally makes referrals; the team reviews them and arranges an assessment if accepted. It is not open to self-referral.", null, "https://www.nhsfife.org/services/all-services/mental-health/community-mental-health-team/", "NHS Fife", { locationLine: "Dunfermline and surrounding area · referral via GP/health professional" });
add("Dunfermline", "programs", "addiction-services-lynebank", "NHS Fife Addiction Services — Dunfermline clinic", "Alcohol and drug treatment, recovery and harm-reduction care", "NHS Fife lists its Addiction Services at Lynebank Hospital in Dunfermline. The service includes nursing assessment, psychosocial interventions, harm reduction and assessment for alcohol detox; call the hospital switchboard for the appropriate service and referral route.", "01383 623623", "https://www.nhsfife.org/services/all-services/addiction-services/", "NHS Fife", { address: "Lynebank Hospital, Halbeath Road, Dunfermline KY11 8JH", locationLine: "Call switchboard to confirm the clinic/referral route · assessment applies" });
add("Dunfermline", "peer", "east-end-eats", "East End Eats — community meal and connection", "Free community café and welcoming social space", "Fife Council lists East End Eats as open to everyone for a meal, conversation and community connection. Contact the organisers to confirm current weekly session and access before travelling; donations are welcome but not required according to the council listing.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Pars Foundation", { address: "KDM Group East End Park, Halbeath Road, Dunfermline KY12 7RB", locationLine: "Tuesday 1pm–3pm listed · check current session" });
add("Dunfermline", "peer", "oasis-dropin", "Oasis Drop-in — Viewfield Baptist Church", "Community café, conversation and social connection", "Fife Council lists a free/donation-based drop-in with soup, sandwiches, tea and coffee. Contact the venue to confirm the current session, accessibility and whether any arrangements have changed.", "01383 620465", "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Viewfield Baptist Church", { address: "Viewfield Centre, 2 Viewfield Terrace, Dunfermline KY12 7HZ", locationLine: "Tuesday noon–2pm listed · confirm before travel" });
add("Dunfermline", "peer", "take-time-tuesday", "Take Time Tuesday — Hope House Church", "Community lunch, crafts and wellbeing activities", "Fife Council lists a weekly friendly chat, light lunch and craft/wellness activity open to everyone. Contact the organiser to check the current time and accessibility before travelling.", "07944 887653", "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Hope House Church", { address: "20 Gordon Terrace, Dunfermline KY11 3BH", locationLine: "Tuesday 11am–1:30pm listed · confirm current session" });
add("Dunfermline", "housing", "homelessness-prevention", "Fife Council — homelessness prevention and temporary accommodation", "Housing assessment and emergency accommodation route", "Fife Council can assess people who are homeless or at risk, help prevent homelessness and offer temporary accommodation if needed. Contact early; accommodation may be outside the preferred area and depends on assessment and availability.", "03451 550033", "https://www.fife.gov.uk/housing/homelessness-and-prevention", "Fife Council", { alternatePhone: "24-hour homeless emergencies: 0800 028 6231", locationLine: "Fife-wide · daytime advice and separate 24/7 emergency number" });
add("Dunfermline", "housing", "home4good-centre", "Home4Good Centre — Dunfermline temporary housing access", "Council temporary accommodation while housing need is assessed", "Fife Council says Home4Good may provide temporary accommodation while it assesses a homelessness situation or arranges an interview. Contact the centre or the council housing team; this is an assessment route, not a promise of immediate vacancy.", null, "https://www.fife.gov.uk/facilities/homeless-accommodation/home4good-centre3", "Fife Council", { email: "Dunfermline.home4good@fife.gov.uk", locationLine: "Temporary accommodation is council-assessed and availability-dependent" });
add("Dunfermline", "food.essentials", "dunfermline-foodbank", "Dunfermline Foodbank — Liberty Centre distribution", "Emergency food parcels through referral vouchers", "Fife Council says Dunfermline Foodbank parcels require a referral voucher from a local agency. Contact a referral partner to discuss need and the voucher route, then confirm collection arrangements and current availability with the foodbank.", null, "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Dunfermline Foodbank", { email: "info@dunfermline.foodbank.org.uk", address: "Liberty Centre, Pitreavie Business Park, Dunfermline KY11 8QS", locationLine: "Referral voucher required · Monday/Wednesday/Friday 4pm–6pm listed · verify first" });
add("Dunfermline", "food.essentials", "baldridgeburn-pantry", "Baldridgeburn Pantry & Café", "Low-cost food pantry with community café and support pop-ups", "Fife Council lists a weekly pantry where people can access fresh and ambient food for a small contribution, with a free cuppa and periodic support-service pop-ups. Contact the centre to confirm current price, session and what is available; stock varies.", "01383 724751", "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Dunfermline Community Learning and Development", { email: "cld.dunfermline@fife.gov.uk", address: "Baldridgeburn Community Centre, Dunfermline KY12 9EH", locationLine: "Tuesday 12:30–2pm listed · £3 or what can be afforded · bring bags" });
add("Dunfermline", "food.essentials", "food-for-your-future", "Food for Your Future Pantry — Touch Community Centre", "Low-cost pantry for fresh, frozen and ambient food", "Fife Council lists a pantry with food and some non-food items for a small contribution. Contact the provider to check membership, current price, opening session and stock before travelling.", "07730 809375", "https://www.fife.gov.uk/benefits-money-advice/accessing-food/city-of-dunfermline", "Fife Council / Food for Your Future", { email: "foodforyourfutureenquiries@gmail.com", address: "Touch Community Centre, 30 Mercer Place, Dunfermline KY11 4UG", locationLine: "Thursday sessions listed · £3 contribution shown · verify before travel" });
add("Dunfermline", "grants", "fife-benefits-money-advice", "Fife Council — Dunfermline benefits and money advice", "Benefit checks, heating-cost support and local appointments", "Fife Council provides a Community Support helpline and local face-to-face or appointment-based sessions in Dunfermline. Contact to discuss benefit entitlement, heating costs, food support and current appointment locations; no award is guaranteed.", "0800 9520330", "https://www.fife.gov.uk/benefits-money-advice/get-support", "Fife Council", { locationLine: "Dunfermline area · weekday helpline and local sessions listed" });
add("Dunfermline", "hotlines", "fife-out-of-hours-homelessness", "Fife Council — 24-hour homeless emergency line", "Out-of-hours housing response for people with nowhere safe to stay", "Call the council's free 24-hour line if you are homeless or have nowhere safe to stay. Staff assess needs and may offer temporary accommodation; call 999 for immediate danger.", "0800 0286231", "https://www.fife.gov.uk/contact-us/contact-us-3/phone-numbers", "Fife Council", { locationLine: "24 hours, every day · Fife-wide · assessment and availability apply" });

// Ayr — named local recovery, advice, housing and food routes in South Ayrshire.
add("Ayr", "programs", "adult-community-mental-health-team", "South Ayrshire Adult Community Mental Health Team", "Adult mental-health assessment and ongoing community care", "South Ayrshire HSCP lists the adult team at Ailsa Hospital. Contact your GP or the team to discuss referral and appointment access; this is not a walk-in crisis service. For urgent danger call 999.", "01292 559777", "https://hscp.south-ayrshire.gov.uk/article/81017/Useful-Contacts", "South Ayrshire Health and Social Care Partnership", { address: "Ailsa Hospital, Dalmellington Road, Ayr KA6 6AB", locationLine: "GP/provider referral and assessment · not emergency response" });
add("Ayr", "programs", "south-ayrshire-recovery-service", "South Ayrshire Treatment and Recovery Team — We Are With You", "Direct-access alcohol and drug recovery support", "The South Ayrshire Alcohol and Drug Partnership describes We Are With You as a direct-access service for people concerned about their own or someone else's drug or alcohol use, with advice, information, signposting and structured support. Call to discuss confidential access and assessment.", "01292 430529", "https://south-ayrshire-adp.scot/get-help/", "South Ayrshire Alcohol and Drug Partnership / We Are With You", { address: "3 Killoch Place, Ayr KA7 2EA", locationLine: "Direct access listed · contact provider to confirm current appointment options" });
add("Ayr", "programs", "ayrshire-council-on-alcohol", "Ayrshire Council on Alcohol", "Confidential alcohol counselling and support for individuals and families", "The local partnership lists confidential individual counselling and support for people affected by their own or another person's drinking. It uses an open referral system; contact the provider to discuss current locations, assessment and appointment availability.", "01292 281238", "https://south-ayrshire-adp.scot/get-help/", "South Ayrshire Alcohol and Drug Partnership / Ayrshire Council on Alcohol", { email: "info@acaayr.org", address: "24 Fullarton Street, Ayr KA7 1UB", locationLine: "Open referral system listed · call to confirm current access" });
add("Ayr", "peer", "connect-south-ayrshire", "Connect South Ayrshire", "Confidential listening, emotional support and connection", "South Ayrshire HSCP lists Connect South Ayrshire as a local support contact. Call to discuss what support is available and how to access it; it is not a replacement for emergency response or specialist clinical care.", "0800 4320510", "https://hscp.south-ayrshire.gov.uk/article/81017/Useful-Contacts", "South Ayrshire Health and Social Care Partnership", { address: "53 Sandgate, Ayr KA7 1DA", locationLine: "South Ayrshire · confirm current hours and service scope" });
add("Ayr", "peer", "south-ayrshire-recovery-groups", "South Ayrshire Recovery Partnership — weekly recovery groups", "Peer recovery activities and community support", "The local Alcohol and Drug Partnership publishes weekly recovery groups and activities. Check its current calendar or contact a listed provider to confirm the group, time, venue and whether drop-in or referral access applies.", null, "https://south-ayrshire-adp.scot/get-help/", "South Ayrshire Alcohol and Drug Partnership", { locationLine: "Ayr and South Ayrshire · group schedule changes; verify before attending" });
add("Ayr", "housing", "housing-options-support", "South Ayrshire Council Housing Options and Support Team", "Housing assessment, homelessness prevention and emergency contact", "The council's Housing Options team advises people who are homeless or at risk. Contact during office hours for assessment; accommodation is assessed and depends on availability. Use the separate out-of-hours standby number if you have nowhere safe overnight.", "0300 1230900", "https://www.south-ayrshire.gov.uk/article/27505/Contact-Housing", "South Ayrshire Council", { address: "80–88 Kyle Street, Ayr KA7 1RZ", alternatePhone: "Out-of-hours homeless standby: 0808 1003151", locationLine: "Office hours listed on council page · housing assessment required" });
add("Ayr", "food.essentials", "food-pantry-ayr", "The Food Pantry @ Ayr", "Low-cost weekly food access for eligible local households", "The pantry lists low-cost food shopping and proof-of-address requirements for its catchment. Contact the provider to confirm current eligibility, item limits, price and opening times; this is a paid pantry, not a free emergency parcel.", "07599 891305", "https://communityjustice.scot/community-support-service/south-ayrshire/ayr-food-pantry/", "Community Justice Scotland / VASA", { email: "enquiries@vasa.scot", address: "12 Arthur Street, Ayr KA7 1QJ", locationLine: "Catchment and proof-of-address rules apply · £4 shop listed · check first" });
add("Ayr", "food.essentials", "support-with-food", "South Ayrshire Council — food support and referral route", "Food-voucher referral and crisis-grant navigation", "The council works with Trussell and other providers offering food vouchers or parcels. Its advice team can explain the referral route and related financial help; food access is assessed and not guaranteed. If there is no money for essentials, apply for the Scottish Welfare Fund through the council.", "0300 1230900", "https://www.south-ayrshire.gov.uk/article/26184/Support-with-Food", "South Ayrshire Council", { locationLine: "South Ayrshire residents · advice/referral route · contact before relying on support" });
add("Ayr", "grants", "information-advice-hub", "South Ayrshire Information and Advice Hub", "Free advice on benefits, debt, food vouchers and household costs", "The council's Information and Advice Team offers appointments and drop-in sessions including in Ayr, plus digital drop-in access on listed days. Contact to confirm the current calendar and referral options; advice can support applications but cannot guarantee grants.", "0300 1230900", "https://www.south-ayrshire.gov.uk/article/24032/Contact-the-Information-and-Advice-Hub", "South Ayrshire Council", { locationLine: "Drop-ins in Ayr and other localities · current calendar and appointment access vary" });
add("Ayr", "grants", "scottish-welfare-fund", "South Ayrshire Scottish Welfare Fund", "Assessed Crisis Grant route for essential living costs", "The council directs residents in financial crisis who cannot meet essential living costs to the Scottish Welfare Fund. Apply through the local authority and ask the Information and Advice Team about support; eligibility and available funds are assessed.", null, "https://www.south-ayrshire.gov.uk/article/24032/Contact-the-Information-and-Advice-Hub", "South Ayrshire Council", { locationLine: "Local authority grant application · assessed; not a guaranteed payment" });
add("Ayr", "hotlines", "south-ayrshire-homeless-standby", "South Ayrshire Council — out-of-hours homeless standby", "Urgent housing contact when the council office is closed", "If you are homeless and need urgent help outside office hours, South Ayrshire Council lists this standby line. Staff assess the situation and advise on next steps; accommodation is not guaranteed. Call 999 for immediate danger.", "0808 1003151", "https://www.south-ayrshire.gov.uk/article/27505/Contact-Housing", "South Ayrshire Council", { locationLine: "Out-of-hours homeless standby · assessment required" });

// Kilmarnock — detailed East Ayrshire treatment, food, housing and money pathways.
add("Kilmarnock", "programs", "radar-addiction-access", "East Ayrshire RADAR — Rapid Access to Drug and Alcohol Support", "Single contact for treatment assessment, harm reduction and family support", "East Ayrshire Council lists RADAR as the contact for people concerned about their own or another person's alcohol or drug use. It can discuss treatment, medication, naloxone, harm reduction and family support. Call for an appointment and ask about out-of-hours NHS 24 access.", "01563 574237", "https://www.east-ayrshire.gov.uk/SocialCareAndHealth/Wellbeing/Help-and-support/Support-directory.aspx", "East Ayrshire Council", { address: "North West Area Centre, Western Road, Kilmarnock KA3 1NQ", locationLine: "Appointment within 24 hours is listed; confirm current access · NHS 24: 111 out of hours" });
add("Kilmarnock", "programs", "east-ayrshire-recovery-hub", "East Ayrshire Recovery Hub", "Community recovery support, training and development", "East Ayrshire Council lists a recovery hub for people affected by drug or alcohol issues, linking recovery support with training and community development. Contact the hub to ask about current activity, eligibility and appointments.", "07497 887458", "https://www.east-ayrshire.gov.uk/SocialCareAndHealth/Wellbeing/Help-and-support/Support-directory.aspx", "East Ayrshire Council / East Ayrshire Recovery Hub", { email: "socialmedia.earh@gmail.com", address: "3–9 John Finnie Street, Kilmarnock", locationLine: "Contact provider to confirm current group and appointment access" });
add("Kilmarnock", "programs", "east-ayrshire-recovery-service", "East Ayrshire Recovery Service — We Are With You", "Free confidential alcohol and drug support", "East Ayrshire Council lists We Are With You as a free confidential recovery service. Contact the provider to discuss direct access, family support and treatment options; a personal assessment determines what support is suitable.", "01563 558777", "https://www.east-ayrshire.gov.uk/SocialCareAndHealth/Wellbeing/Help-and-support/Support-directory.aspx", "East Ayrshire Council / We Are With You", { locationLine: "Kilmarnock/East Ayrshire · weekday contact listed; confirm current service access" });
add("Kilmarnock", "peer", "east-ayrshire-recovery-network", "East Ayrshire Recovery Network", "Peer and community recovery-service, event and naloxone navigator", "The council describes the Recovery Network as a directory of services, events and naloxone access for people directly or indirectly affected by alcohol and drug use. Use it to find current local options and confirm meeting details with each provider.", null, "https://www.earecoverynetwork.co.uk/", "East Ayrshire Council / East Ayrshire Recovery Network", { locationLine: "Regional navigator · verify each provider's current schedule and access" });
add("Kilmarnock", "peer", "eacha-community-support", "East Ayrshire Churches Homelessness Action (EACHa)", "Community meals and practical support for people facing homelessness or crisis", "East Ayrshire Council lists EACHa's weekly Kilmarnock lunches and crisis assistance. Contact the coordinator to confirm current meal sessions and any support available; this is a community service, not accommodation or emergency response.", "07515 402805", "https://www.east-ayrshire.gov.uk/Resources/PDF/S/Suicide-Support-Directory.pdf", "East Ayrshire Council / EACHa", { email: "info@earecoverynetwork.co.uk", address: "New Laigh Kirk Halls, 35 John Finnie Street, Kilmarnock", locationLine: "Weekly meals listed · confirm current timetable" });
add("Kilmarnock", "housing", "housing-options-homelessness", "East Ayrshire Housing Options — Kilmarnock", "Housing and homelessness assessment and tenancy support", "The council lists its Housing Options team at the Opera House in Kilmarnock. Contact about homelessness, tenancy problems and support to retain or move into housing; needs are assessed and no accommodation is guaranteed.", "01563 554400", "https://www.east-ayrshire.gov.uk/Housing/CouncilHousing/Support-for-tenants/Housingsupport.aspx", "East Ayrshire Council", { email: "homelessness@east-ayrshire.gov.uk", address: "Opera House, 8 John Finnie Street, Kilmarnock KA1 1DD", locationLine: "Phone for assessment and current appointment access" });
add("Kilmarnock", "housing", "housing-support-tenancy", "East Ayrshire Council — housing support to sustain a tenancy", "Practical support with benefits, bills, moving and tenancy stability", "Housing Support Officers can help eligible residents with forms, benefits, budgeting, furniture, housing issues and referrals to mental-health or addiction support. Contact Housing Options to discuss an assessment and local team; support is not a housing allocation.", "01563 554400", "https://www.east-ayrshire.gov.uk/Housing/CouncilHousing/Support-for-tenants/Housingsupport.aspx", "East Ayrshire Council", { email: "housing@east-ayrshire.gov.uk", locationLine: "Eligibility and support assessment apply · Kilmarnock area teams listed" });
add("Kilmarnock", "food.essentials", "ayrshire-east-foodbank-belford", "Ayrshire East Food Bank — Belford Mill", "Emergency food parcel and additional essentials support", "East Ayrshire Council lists the Belford Mill centre for food parcels, toiletries, pet food and signposting. The area food bank uses an appointment system; contact the central line to ask about referral and arrange a current session before attending.", "01563 574000", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Food-provision/Food-provision-sites.aspx", "East Ayrshire Council / Ayrshire East Food Bank", { address: "16 Brewery Road, Kilmarnock KA1 3HZ", locationLine: "Appointment system · ask about referral, current session and food availability" });
add("Kilmarnock", "food.essentials", "east-ayrshire-foodbank-old-irvine", "Ayrshire East Food Bank — Old Irvine Road", "Food-bank provision and support", "The council lists this Kilmarnock foodbank site and a telephone appointment process. Call the central number during its listed call times to ask about referral and arrange a session; no parcel or current stock is guaranteed.", "01563 574000", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Food-provision/Food-provision-sites.aspx", "East Ayrshire Council / Ayrshire East Food Bank", { address: "11–15 Old Irvine Road, Kilmarnock KA1 2BD", locationLine: "Appointment system · call between listed weekday appointment hours" });
add("Kilmarnock", "food.essentials", "fefa-pantry", "Food and Essentials for All (FEFA) — Onthank", "Low-cost or assessed collection of food and household essentials", "East Ayrshire Council lists this collection service at NWKLEUS in Onthank and a currently stated £2 charge per request. Contact the provider to confirm current cost, eligibility, collection time and available items before travelling.", "07366 147178", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Food-provision/Food-provision-sites.aspx", "East Ayrshire Council / Food and Essentials for All", { address: "NWKLEUS, Kirkton Road, Onthank, Kilmarnock KA3 2DF", locationLine: "Collection only · £2 charge listed · reconfirm current terms and stock" });
add("Kilmarnock", "food.essentials", "corner-cupboard", "Corner Cupboard — Muslim Education Centre", "Community food support and collection", "East Ayrshire Council lists a Saturday food-support session at the Muslim Education Centre. Contact the organiser to check current access, any referral or eligibility rules and food availability before travelling.", "07944 193674", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Food-provision/Food-provision-sites.aspx", "East Ayrshire Council / Corner Cupboard", { email: "cornercupboard57@gmail.com", address: "Muslim Education Centre, London Road, Kilmarnock", locationLine: "Saturday session listed · verify current opening and access" });
add("Kilmarnock", "grants", "welfare-rights-service", "East Ayrshire Welfare Rights Service / EA Money", "Free advice on benefits, debt, rent arrears and grant applications", "The council's Welfare Rights Service can check benefit entitlement, challenge decisions and help with Scottish Welfare Fund and Council Tax Reduction claims. Contact or use its referral form; advice supports applications but does not guarantee an award.", "0800 3897750", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Benefits/welfare-rights/welfare-rights-service.aspx", "East Ayrshire Council", { email: "welfarerightsservice@east-ayrshire.gov.uk", locationLine: "East Ayrshire residents · contact/referral and assessment apply" });
add("Kilmarnock", "grants", "scottish-welfare-fund", "East Ayrshire Scottish Welfare Fund", "Discretionary Crisis Grants and Community Care Grants", "East Ayrshire Council accepts applications for discretionary grants through the Scottish Welfare Fund. The fund is budget-limited and applications are assessed by need; use the online route where possible and ask the council for accessible application support.", "01563 554400", "https://www.east-ayrshire.gov.uk/CouncilAndGovernment/Benefits/Scottish-Welfare-Fund.aspx", "East Ayrshire Council", { email: "scottishwelfarefund@east-ayrshire.gov.uk", address: "Opera House, 8 John Finnie Street, Kilmarnock KA1 1DD", locationLine: "Apply to council where you live · discretionary, assessed and budget-limited" });
add("Kilmarnock", "hotlines", "east-ayrshire-citizens-advice-crisis", "East Ayrshire Citizens Advice — cost-of-living crisis line", "Urgent advice where hardship threatens food, utilities or housing", "East Ayrshire Council lists a Citizens Advice crisis line for people facing loss of utilities, no access to food or threat of homelessness. Call for advice and referral; it is not emergency dispatch. For immediate danger call 999; NHS 24 is 111.", "01563 544744", "https://www.east-ayrshire.gov.uk/socialcareandhealth/wellbeing/financial-help/financial-help.aspx", "East Ayrshire Council / Citizens Advice East Ayrshire", { locationLine: "Local crisis advice line · call for current access and referral; not a cash-grant promise" });
add("Kilmarnock", "hotlines", "know-the-score", "Know the Score — confidential drug information line", "Information, harm-reduction guidance and treatment signposting", "East Ayrshire Council lists Know the Score as a confidential source of drug-use information and advice. Call to discuss concerns or find a treatment route; it is an advice service, not an emergency response or treatment clinic.", "0800 5875879", "https://www.east-ayrshire.gov.uk/SocialCareAndHealth/Wellbeing/Help-and-support/Support-directory.aspx", "East Ayrshire Council / Know the Score", { locationLine: "Daily 8am–11pm listed · for immediate medical danger call 999" });

